export function getRetainedExampleHome(key: string): RetainedExampleHome | undefined {
    return retainedExampleHomes.find(home => home[0] === key);
}

export function getRetainedExampleForLegacyIdentity(identity: string, demonstrationId: DemonstrationId): RetainedExampleHome | undefined {
    const alias = legacyExampleAliases.find(entry => entry[0] === identity && entry[3] === demonstrationId);
    return alias ? getRetainedExampleHome(alias[6]) : undefined;
}

